from fractions import Fraction
import json


def term_sum(k):
    # Term j (j = 0..k): [prod_{i=0}^{j-1} (2k-2i)] / [prod_{i=0}^{j} (2k+1-2i)]
    total = Fraction(0)
    P = 1
    Q = 1
    for j in range(k + 1):
        if j > 0:
            P *= (2 * k - 2 * (j - 1))
        Q *= (2 * k + 1 - 2 * j)
        total += Fraction(P, Q)
    return total


ks = list(range(1, 13))
values = {k: term_sum(k) for k in ks}
constant = values[ks[0]]

if all(v == constant for v in values.values()):
    result = {
        "final_answer": str(constant),
        "evidence": {
            "method": "exact Fraction enumeration of terms j=0..k",
            "k_checked": ks,
            "values": {str(k): str(values[k]) for k in ks},
            "all_equal": True,
        },
    }
    print(json.dumps(result))
else:
